def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator lines are uniform and contain a color distinct from the background.
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(size, separators):
        cuts = [-1] + separators + [size]
        return [(cuts[i] + 1, cuts[i + 1]) for i in range(len(cuts) - 1)]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    source = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
                break
        if source is not None:
            break

    out = [row[:] for row in grid]
    if source is None:
        return out

    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = source[r - r0][c - c0]
    return out
